// ════════════════════════════════════════════════════════════════
// Glossaire statique FR → IT (mode « Italiano »).
//
// Même rôle que UI_GLOSSARY (glossary.js) pour l'anglais, UI_GLOSSARY_ES
// (glossaryEs.js) pour l'espagnol et UI_GLOSSARY_DE (glossaryDe.js) pour
// l'allemand : le vocabulaire d'interface le plus fréquent bascule
// instantanément, hors ligne et sans appel IA. Le reste (recettes, étapes,
// notes…) part à l'IA puis au cache.
//
// MÊMES CLÉS que UI_GLOSSARY, dans le même ordre : toute entrée ajoutée au
// glossaire anglais doit l'être ici aussi. `npm run lint:glossary` le vérifie.
//
// Registre : italien standard, compris au Tessin et en Italie, ton d'interface
// concis. Actions à la forme des logiciels italiens (« Salva », « Elimina »,
// « Annulla », « Modifica », « Stampa »), phrases adressées à la personne à la
// forme de courtoisie (Lei, sans majuscule de révérence dans le verbe),
// guillemets « » sans espace. Vocabulaire métier aligné sur la tâche
// `translate` d'ai-proxy : carte → menu (carte des boissons → carta delle
// bevande), carte bancaire → carta bancaria, fiche technique → scheda tecnica,
// fiche salle → scheda di sala, perte → perdita, pointage → timbratura
// (pointer → timbrare), planning → piano dei turni, inventaire → inventario,
// établissement → struttura, commande → ordine (bon de cuisine → comanda,
// ticket de caisse → conto), dressage → impiattamento, réservation →
// prenotazione, couverts → coperti, relevé → rilevazione, étages → piani,
// femme de chambre → cameriera ai piani, TVA → IVA, CCNT → CCNL, fiduciaire →
// fiduciaria. Mise en place, chef de partie et commis restent tels quels.
// ════════════════════════════════════════════════════════════════

