  "Ces chiffres sont réservés à la direction et aux personnes qui règlent les factures. Demandez à votre consultant le droit « Régler les factures ».": "Queste cifre sono riservate alla direzione e alle persone che saldano le fatture. Chieda al Suo consulente il diritto «Salda le fatture».",
  "La comptabilité n'est pas encore activée sur la base de données.": "La contabilità non è ancora attivata nel database.",
  "Les achats et les marges se lisent déjà ; la saisie du chiffre d'affaires, les charges fixes, les salaires et la banque arriveront avec elle.": "Gli acquisti e i margini si leggono già; l'inserimento del fatturato, i costi fissi, i salari e la banca arriveranno con essa.",
  "La comptabilité de l'app prépare vos chiffres et vos pièces pour la fiduciaire. Elle ne tient pas les comptes et n'établit ni le décompte TVA officiel ni les salaires.": "La contabilità dell'app prepara le Sue cifre e i Suoi giustificativi per la fiduciaria. Non tiene i conti e non redige né il rendiconto IVA ufficiale né i salari.",
  "Aucun inventaire validé : la période d'inventaire commence au premier inventaire validé.": "Nessun inventario convalidato: il periodo d'inventario inizia al primo inventario convalidato.",
  "Montants TVA comprise, comme sur le ticket de caisse du soir.": "Importi IVA inclusa, come sullo scontrino di cassa della sera.",
  "La caisse a enregistré": "La cassa ha registrato",
  "ce jour-là. Une saisie ici la remplace pour ce jour.": "quel giorno. Un inserimento qui la sostituisce per quel giorno.",
  "Seule une personne qui règle les factures peut saisir le chiffre d'affaires.": "Solo una persona che salda le fatture può inserire il fatturato.",
  "Une charge fixe se saisit une fois : l'app la répartit sur chaque mois. N'importez pas aussi sa facture dans Factures & achats, sinon elle compte deux fois.": "Un costo fisso si inserisce una volta: l'app lo ripartisce su ogni mese. Non importi anche la sua fattura in Fatture & acquisti, altrimenti conta due volte.",
  "Supprimer cette charge ?": "Eliminare questo costo?",
