  "Les heures de relevé ne sont pas les mêmes d'une maison à l'autre : un seul service qui démarre à 6h ne se relève pas comme un double service midi et soir. Réglez ici les heures de l'établissement : la carte de l'accueil HACCP dit à l'équipe quand relever, et le tableau de bord signale un relevé en retard. Un relevé en dehors de ces heures reste toujours possible.": "Le ore di rilevazione non sono le stesse da una casa all'altra: un servizio unico che inizia alle 6 non si rileva come un doppio servizio pranzo e cena. Imposti qui le ore della struttura: la scheda della home HACCP dice alla squadra quando rilevare, e la dashboard segnala una rilevazione in ritardo. Una rilevazione fuori da queste ore resta sempre possibile.",
