  "Sur place, le taux de la catégorie s'applique. Quand un ticket est marqué à emporter, seules les catégories cochées passent au taux réduit ; l'alcool reste toujours au taux normal. Le taux est figé sur chaque ligne à l'encaissement.": "Sul posto si applica l'aliquota della categoria. Quando un conto è segnato da asporto, solo le categorie spuntate passano all'aliquota ridotta; l'alcol resta sempre all'aliquota normale. L'aliquota è fissata su ogni riga all'incasso.",
