  "Dossier de caisse téléchargé ; des jours non clôturés sont restés dehors, voir lisez-moi.txt.": "Dossier di cassa scaricato; alcuni giorni non chiusi sono rimasti fuori, veda lisez-moi.txt.",
  "Dossier de caisse téléchargé.": "Dossier di cassa scaricato.",
  "Terminal de paiement": "Terminale di pagamento",
  "Au tap sur « Carte », la caisse envoie le montant au terminal ; le client paie sur le terminal ; la caisse reçoit « accepté » ou « refusé » et pose le paiement toute seule.": "Al tocco su «Carta», la cassa invia l'importo al terminale; il cliente paga sul terminale; la cassa riceve «accettato» o «rifiutato» e registra il pagamento da sola.",
  "La caisse ne voit jamais une carte : ni numéro, ni date, ni code. Elle garde seulement le résultat (marque, quatre derniers chiffres, code d'autorisation). L'argent va du prestataire à la maison, sans passer par l'app.": "La cassa non vede mai una carta: né numero, né data, né codice. Conserva solo il risultato (marca, ultime quattro cifre, codice di autorizzazione). Il denaro va dal fornitore alla casa, senza passare dall'app.",
  "Terminaux reliés": "Terminali collegati",
  "Les terminaux n'ont pas pu être lus. Fermez les Réglages et rouvrez-les.": "I terminali non si sono potuti leggere. Chiuda le Impostazioni e le riapra.",
  "Aucun terminal relié : les cartes s'encaissent à la main, comme aujourd'hui.": "Nessun terminale collegato: le carte si incassano a mano, come oggi.",
  "Terminal simulé": "Terminale simulato",
