  "Il ne sert que les tickets du mode test : aucun argent ne bouge, aucun vrai ticket ne peut être payé par lui.": "Serve solo i conti della modalità test: nessun denaro si muove, nessun conto vero può essere pagato con esso.",
  "Ce terminal a déjà encaissé un paiement réel accepté.": "Questo terminale ha già incassato un pagamento reale accettato.",
  "Ce terminal n'a pas encore encaissé de paiement réel accepté : faites un premier paiement de 1 franc avant le service.": "Questo terminale non ha ancora incassato un pagamento reale accettato: faccia un primo pagamento di 1 franco prima del servizio.",
  "Garder": "Mantieni",
  "Retirer ce terminal": "Rimuovi questo terminale",
  "Terminaux retirés :": "Terminali rimossi:",
  "Leurs paiements passés restent dans la caisse ; un remboursement se fait alors chez le prestataire.": "I loro pagamenti passati restano nella cassa; un rimborso si fa allora presso il fornitore.",
  "Relier un terminal": "Collega un terminale",
  "Prestataire": "Fornitore del servizio",
  "Clé": "Chiave",
  "Jumelage": "Abbinamento",
  "Aucun prestataire réel n'est encore proposé. Le terminal simulé sert à s'entraîner en mode test ; un vrai terminal sera ajouté quand son prestataire aura confirmé ses règles et fourni un moyen d'essai sans argent réel.": "Nessun fornitore reale è ancora proposto. Il terminale simulato serve per esercitarsi in modalità test; un terminale vero sarà aggiunto quando il suo fornitore avrà confermato le sue regole e fornito un mezzo di prova senza denaro reale.",
  "Nom du terminal, tel que l'équipe le verra": "Nome del terminale, come lo vedrà la squadra",
  "Terminal du bar": "Terminale del bar",
  "Numéro de série, lu sous le terminal": "Numero di serie, letto sotto il terminale",
  "Saisie masquée": "Inserimento nascosto",
  "La clé part une seule fois vers le serveur, qui la range dans son coffre. Elle ne revient jamais à l'écran : seuls ses quatre derniers caractères seront rappelés.": "La chiave parte una sola volta verso il server, che la ripone nella sua cassaforte. Non torna mai sullo schermo: saranno ricordati solo i suoi ultimi quattro caratteri.",
  "Code de jumelage": "Codice di abbinamento",
  "Code lu sur le terminal": "Codice letto sul terminale",
  "Le code s'affiche sur le terminal et ne sert qu'une fois : il prouve que le terminal est devant vous.": "Il codice si visualizza sul terminale e serve una sola volta: prova che il terminale è davanti a Lei.",
  "Relier ce terminal": "Collega questo terminale",
  "Relier ou retirer un terminal : consultant ou patron de la maison.": "Collegare o rimuovere un terminale: consulente o titolare della casa.",
  "Plafond d'un paiement sur le terminal, en CHF": "Tetto di un pagamento sul terminale, in CHF",
  "Au-dessus de ce montant, pourboire compris, la caisse n'envoie rien au terminal : une erreur de saisie ne part pas en débit.": "Oltre questo importo, mancia compresa, la cassa non invia nulla al terminale: un errore di inserimento non diventa un addebito.",
