  "Somme de la TVA de chaque ticket, arrondie au centime par ticket et par taux.": "Somma dell'IVA di ogni conto, arrotondata al centesimo per conto e per aliquota.",
  "Nombre de tickets numérotés encaissés ; un ticket annulé depuis reste compté le jour de sa vente.": "Numero di conti numerati incassati; un conto annullato in seguito resta contato il giorno della sua vendita.",
