  "Couverts saisis sur les tickets encaissés, moins ceux des tickets annulés.": "Coperti inseriti sui conti incassati, meno quelli dei conti annullati.",
  "Chiffre d'affaires TVA comprise divisé par les tickets, annulations déduites ; recalculé sur chaque pas.": "Fatturato IVA inclusa diviso per i conti, annullamenti dedotti; ricalcolato su ogni passo.",
  "Chiffre d'affaires TVA comprise divisé par les couverts ; recalculé sur chaque pas.": "Fatturato IVA inclusa diviso per i coperti; ricalcolato su ogni passo.",
  "Ce que la maison garde par moyen de paiement : montants et arrondis des espèces, annulations déduites, pourboires à part.": "Ciò che la casa trattiene per metodo di pagamento: importi e arrotondamenti dei contanti, annullamenti dedotti, mance a parte.",
  "Pourboires saisis à l'encaissement, hors chiffre d'affaires.": "Mance inserite all'incasso, fuori fatturato.",
  "Écart entre les espèces comptées et les espèces attendues, à la dernière clôture de chaque jour.": "Scarto tra i contanti contati e i contanti attesi, all'ultima chiusura di ogni giorno.",
  "Quantités vendues, annulations déduites, offerts compris.": "Quantità vendute, annullamenti dedotti, offerti compresi.",
  "Somme des lignes vendues, TVA comprise : elle fait le chiffre d'affaires de la période.": "Somma delle righe vendute, IVA inclusa: forma il fatturato del periodo.",
  "Montant des remises accordées sur les tickets encaissés.": "Importo degli sconti concessi sui conti incassati.",
  "Valeur au prix d'origine des lignes offertes.": "Valore al prezzo d'origine delle righe offerte.",
  "De l'ouverture du ticket à son encaissement, sur les ventes servies à table ; recalculée sur chaque pas.": "Dall'apertura del conto al suo incasso, sulle vendite servite al tavolo; ricalcolata su ogni passo.",
  "Couverts des réservations honorées, non pointées et prévues ; ni les annulées ni les no-show.": "Coperti delle prenotazioni onorate, non registrate e previste; né le annullate né i no-show.",
  "Réservations valides, annulées exclues. Une table est une réservation, pas une table de la salle.": "Prenotazioni valide, annullate escluse. Un tavolo è una prenotazione, non un tavolo della sala.",
  "Réservations marquées no-show.": "Prenotazioni segnate no-show.",
  "No-show divisés par les réservations échues ; recalculé sur chaque pas.": "No-show divisi per le prenotazioni scadute; ricalcolato su ogni passo.",
