  "Réservations passées restées sans arrivée ni no-show, divisées par les réservations échues.": "Prenotazioni passate rimaste senza arrivo né no-show, divise per le prenotazioni scadute.",
  "Couverts divisés par la capacité des services ouverts, d'après les réglages de la réservation en ligne.": "Coperti divisi per la capacità dei servizi aperti, secondo le impostazioni della prenotazione online.",
  "Couverts divisés par les réservations comptées ; recalculé sur chaque pas.": "Coperti divisi per le prenotazioni contate; ricalcolato su ogni passo.",
  "Couverts divisés par les jours ouverts du pas ; sans réglages, par les jours qui ont une réservation.": "Coperti divisi per i giorni aperti del passo; senza impostazioni, per i giorni che hanno una prenotazione.",
  "Montant des factures d'achat non exclues : total hors TVA, à défaut TVA comprise, à défaut somme des lignes lues. Jour de la date de facture.": "Importo delle fatture d'acquisto non escluse: totale IVA esclusa, in mancanza IVA inclusa, in mancanza somma delle righe lette. Giorno della data della fattura.",
  "Nombre de factures d'achat qui portent un montant ; les bons de livraison et de commande ne comptent pas.": "Numero di fatture d'acquisto che portano un importo; le bolle di consegna e i buoni d'ordine non contano.",
  "Chiffre du jour saisi ou clôturé par la caisse, à défaut ventes de la caisse reliée, plus les notes de séjour d'un hôtel.": "Incasso del giorno inserito o chiuso dalla cassa, in mancanza vendite della cassa collegata, più i conti di soggiorno di un albergo.",
  "Ventes moins la TVA, calculée sur le total de chaque taux : la somme des points peut s'écarter du total de quelques centimes.": "Vendite meno l'IVA, calcolata sul totale di ogni aliquota: la somma dei punti può scostarsi dal totale di qualche centesimo.",
  "Achats hors TVA de la période, par date de facture, avec la règle des Analyses des dépenses.": "Acquisti IVA esclusa del periodo, per data della fattura, con la regola delle Analisi delle spese.",
  "Coût matière divisé par le chiffre d'affaires hors TVA ; recalculé sur chaque pas.": "Costo materia diviso per il fatturato IVA escluso; ricalcolato su ogni passo.",
