  "Charges fixes saisies, au prorata des jours du pas.": "Costi fissi inseriti, in proporzione ai giorni del passo.",
  "Estimation depuis les heures pointées, les salaires saisis et les charges sociales. Réservé à la direction.": "Stima dalle ore timbrate, dai salari inseriti e dagli oneri sociali. Riservato alla direzione.",
