  "En mode test, les tickets ouverts sur ce poste ne comptent dans aucun chiffre. Les autres postes continuent de vendre normalement.": "In modalità test, i conti aperti su questa postazione non contano in nessuna cifra. Le altre postazioni continuano a vendere normalmente.",
  "Ce poste est en mode test : rien de ce qui s'y vend ne compte dans les chiffres. Pour revenir aux vraies ventes, ouvrez la caisse et touchez « Quitter le mode test » dans le bandeau.": "Questa postazione è in modalità test: niente di ciò che vi si vende conta nelle cifre. Per tornare alle vendite vere, apra la cassa e tocchi «Esci dalla modalità test» nel banner.",
