  "Réservations non annulées dont la date de prise est connue ; par délai, combien de jours avant le service elles ont été prises.": "Prenotazioni non annullate di cui è nota la data di inserimento; per anticipo, quanti giorni prima del servizio sono state prese.",
  "Jours entre la prise de la réservation et le service, en moyenne ; une saisie après coup compte zéro. Recalculé sur chaque pas.": "Giorni tra l'inserimento della prenotazione e il servizio, in media; un inserimento a posteriori conta zero. Ricalcolato su ogni passo.",
  "La moitié des réservations sont prises moins de jours avant le service, l'autre moitié plus. Recalculé sur chaque pas.": "Metà delle prenotazioni sono prese meno giorni prima del servizio, l'altra metà di più. Ricalcolato su ogni passo.",
  "Réservations comptées marquées comme groupe.": "Prenotazioni contate segnate come gruppo.",
  "Réservations comptées placées sur au moins une table du plan de salle, divisées par les réservations comptées.": "Prenotazioni contate collocate su almeno un tavolo della pianta della sala, divise per le prenotazioni contate.",
  "Réservations comptées reliées à une fiche client, divisées par les réservations comptées.": "Prenotazioni contate collegate a una scheda cliente, divise per le prenotazioni contate.",
  "Fiches clients différentes parmi les réservations comptées ; recalculé sur chaque pas, un client présent sur deux pas compte dans chacun.": "Schede clienti diverse tra le prenotazioni contate; ricalcolato su ogni passo, un cliente presente su due passi conta in ciascuno.",
  "Fiches clients avec au moins une réservation honorée ; recalculé sur chaque pas.": "Schede clienti con almeno una prenotazione onorata; ricalcolato su ogni passo.",
  "Fiches clients avec au moins deux réservations honorées dans le pas ; recalculé sur chaque pas.": "Schede clienti con almeno due prenotazioni onorate nel passo; ricalcolato su ogni passo.",
