  "Couverts divisés par le nombre de semaines de la période, comme les chiffres clés du rapport ; recalculé sur chaque pas.": "Coperti divisi per il numero di settimane del periodo, come le cifre chiave del rapporto; ricalcolato su ogni passo.",
