  "Comme l'appareil suit le réglage clair ou sombre du téléphone, de la tablette ou de l'ordinateur. Le bouton de la barre du haut bascule entre clair et sombre.": "Come il dispositivo segue l'impostazione chiara o scura del telefono, del tablet o del computer. Il pulsante della barra in alto passa da chiaro a scuro.",
  "Le texte de l'app sur cet appareil. Les exports PDF ne changent pas.": "Il testo dell'app su questo dispositivo. Le esportazioni PDF non cambiano.",
  "Hauteur des lignes, des boutons et des champs, et marges de la page. Compacte se règle à la souris : au doigt, chaque cible garde 44 px.": "Altezza delle righe, dei pulsanti e dei campi, e margini della pagina. Compatta si imposta con il mouse: al tocco, ogni bersaglio mantiene 44 px.",
  "Le bouton principal, la pilule choisie et l'entrée choisie du menu. Pétrole est la couleur de la marque.": "Il pulsante principale, la pillola scelta e la voce scelta del menu. Petrolio è il colore del marchio.",
  "Plus de fondus ni de glissements : les écrans changent d'un coup.": "Niente più dissolvenze né scorrimenti: le schermate cambiano di colpo.",
  "Textes secondaires plus foncés, filets et contours plus marqués.": "Testi secondari più scuri, filetti e contorni più marcati.",
  "Original garde le texte tel qu'il a été saisi. English, Español, Deutsch et Italiano traduisent l'écran, pas les données. Le sélecteur de la barre du haut fait la même chose.": "Original mantiene il testo così come è stato inserito. English, Español, Deutsch e Italiano traducono lo schermo, non i dati. Il selettore della barra in alto fa la stessa cosa.",
  "Ouvrir l'app sur": "Apri l'app su",
  "La dernière page ouverte": "L'ultima pagina aperta",
  "La page d'accueil": "La home",
  "Au lancement, sur cet appareil. Une notification touchée ouvre toujours sa page, et un rechargement garde la page en cours.": "All'avvio, su questo dispositivo. Una notifica toccata apre sempre la sua pagina, e un ricaricamento mantiene la pagina in corso.",
