  "L'app se recharge pour changer de présentation.": "L'app si ricarica per cambiare presentazione.",
  "Recharger l'app": "Ricarica l'app",
  "Automatique choisit d'après l'écran. Ordinateur : le menu sur le côté. Tablette et Téléphone : la page d'accueil en tuiles.": "Automatico sceglie in base allo schermo. Computer: il menu sul lato. Tablet e Telefono: la home a riquadri.",
  "Les modules avec leur nom plutôt que le rail d'icônes. Le bouton à gauche du titre et Ctrl + B font la même chose.": "I moduli con il loro nome piuttosto che la barra di icone. Il pulsante a sinistra del titolo e Ctrl + B fanno la stessa cosa.",
  "Glisser depuis le bord gauche de l'écran pour revenir en arrière. Automatique : seulement dans l'app installée sur iPhone et iPad, où le système n'a pas ce geste.": "Scorrere dal bordo sinistro dello schermo per tornare indietro. Automatico: solo nell'app installata su iPhone e iPad, dove il sistema non ha questo gesto.",
