  "à côté d'une tâche : elle vous rapporte des points.": "accanto a un compito: Le fa guadagnare punti.",
  "Ils se gagnent avec les relevés des températures, la traçabilité, les factures, les pertes et l'inventaire.": "Si guadagnano con le rilevazioni delle temperature, la tracciabilità, le fatture, le perdite e l'inventario.",
  "Pointer à l'heure vous rapporte aussi": "Timbrare puntuale Le fa guadagnare anche",
  "Avec vos points, choisissez du matériel pro dans la boutique.": "Con i Suoi punti, scelga attrezzatura professionale nel negozio.",
  "L'équipe gagne des points à chaque tâche faite dans l'app.": "La squadra guadagna punti a ogni compito fatto nell'app.",
  "Elle les échange contre du matériel pro dans la boutique.": "Li scambia con attrezzatura professionale nel negozio.",
  "Avec « Personnaliser », ajoutez, retirez ou déplacez les widgets.": "Con «Personalizza», aggiunga, rimuova o sposti i widget.",
  "Choisissez la taille de chaque widget.": "Scelga la dimensione di ogni widget.",
  "Vous retrouvez le même tableau sur tous vos appareils.": "Ritrova la stessa dashboard su tutti i Suoi dispositivi.",
  "À la caisse : choisissez la table, ajoutez les plats, puis appuyez sur Envoyer.": "In cassa: scelga il tavolo, aggiunga i piatti, poi prema Invia.",
  "En cuisine, chaque table arrive sur un seul bon.": "In cucina, ogni tavolo arriva su una sola comanda.",
  "Quand la cuisine coche un plat, le serveur est prévenu.": "Quando la cucina spunta un piatto, il cameriere viene avvisato.",
  "En fin de repas, encaissez ; en fin de journée, clôturez la caisse.": "A fine pasto, incassi; a fine giornata, chiuda la cassa.",
