  "Photo peu lisible. Reprenez-la à plat, bien éclairée, le document entier dans le cadre.": "Foto poco leggibile. La riscatti in piano, ben illuminata, con tutto il documento nell'inquadratura.",
  "Les lignes lues ne donnent pas le total du document. Vérifiez la lecture.": "Le righe lette non danno il totale del documento. Verifichi la lettura.",
