  "Horaires et fermetures": "Orari e chiusure",
  "Jours de fermeture et vacances : ni alerte ni relevé attendu ces jours-là": "Giorni di chiusura e vacanze: né avvisi né rilevazioni attese in quei giorni",
  "Objectifs": "Obiettivi",
  "Coût matière, coût du personnel et chiffre visés, tracés dans Statistiques": "Costo materia, costo del personale e fatturato mirati, tracciati in Statistiche",
  "Planning : temps de travail": "Piano dei turni: tempo di lavoro",
  "Temps de travail": "Tempo di lavoro",
  "Repos, pauses, journée et semaine les plus longues, signalés dans la grille": "Riposo, pause, giornata e settimana più lunghe, segnalati nella griglia",
  "Planning : pointage": "Piano dei turni: timbratura",
  "Arrivée en avance et arrondi des heures comptées": "Arrivo in anticipo e arrotondamento delle ore contate",
  "Chaque semaine. Ces jours-là, aucune alerte de pointage, de relevé HACCP ni de ventes n'est envoyée, et le planning les marque « Fermé ».": "Ogni settimana. In quei giorni non viene inviato alcun avviso di timbratura, di rilevazione HACCP né di vendite, e il piano dei turni li segna «Chiuso».",
  "Périodes de fermeture": "Periodi di chiusura",
  "Vacances, travaux, privatisation : du premier au dernier jour fermé, compris.": "Vacanze, lavori, evento privato: dal primo all'ultimo giorno chiuso, compresi.",
  "Aucune période de fermeture.": "Nessun periodo di chiusura.",
  "Du": "Dal",
  "Au": "Al",
  "Motif (facultatif)": "Motivo (facoltativo)",
  "Vacances d'hiver": "Vacanze invernali",
  "Indiquez le premier et le dernier jour fermés.": "Indichi il primo e l'ultimo giorno chiusi.",
  "Le dernier jour vient avant le premier.": "L'ultimo giorno viene prima del primo.",
  "Les objectifs se tracent dans Statistiques, sur le graphique de la mesure, et l'écart s'y lit en vert ou en rouge. Un champ vide : pas d'objectif.": "Gli obiettivi si tracciano in Statistiche, sul grafico della misura, e lo scarto vi si legge in verde o in rosso. Un campo vuoto: nessun obiettivo.",
  "Coût matière visé": "Costo materia mirato",
  "En pour cent du chiffre d'affaires hors TVA.": "In percentuale del fatturato IVA esclusa.",
  "Coût du personnel visé": "Costo del personale mirato",
  "En pour cent du chiffre d'affaires hors TVA. Visible de la direction seule, comme la mesure.": "In percentuale del fatturato IVA esclusa. Visibile solo alla direzione, come la misura.",
  "Chiffre d'affaires visé": "Fatturato mirato",
  "Par mois, hors TVA.": "Al mese, IVA esclusa.",
  "Les réglages de la maison ne se lisent pas pour le moment. Réessayez dans un instant.": "Le impostazioni della casa non si leggono per il momento. Riprovi tra un istante.",
  "Contrôler le temps de travail": "Controlla il tempo di lavoro",
  "Le planning signale, sur l'horaire concerné, ce qui sort des règles ci-dessous. Il ne bloque rien. Seules les personnes qui écrivent le planning le voient.": "Il piano dei turni segnala, sull'orario interessato, ciò che esce dalle regole qui sotto. Non blocca nulla. Lo vedono solo le persone che scrivono il piano dei turni.",
  "Repos entre deux journées": "Riposo tra due giornate",
  "La loi sur le travail demande 11 heures de suite ; elles peuvent descendre à 8 heures une fois par semaine.": "La legge sul lavoro chiede 11 ore di seguito; possono scendere a 8 ore una volta a settimana.",
  "Pauses de la loi": "Pause di legge",
  "15 minutes au-delà de 5 h 30 de travail, 30 minutes au-delà de 7 h, 1 heure au-delà de 9 h. La coupure d'un service coupé compte comme pause.": "15 minuti oltre 5 h 30 di lavoro, 30 minuti oltre 7 h, 1 ora oltre 9 h. L'interruzione di un turno spezzato conta come pausa.",
  "Journée la plus longue": "Giornata più lunga",
  "Heures travaillées dans le jour, pauses déduites.": "Ore lavorate nel giorno, pause dedotte.",
  "Semaine la plus longue": "Settimana più lunga",
  "Du lundi au dimanche. La loi fixe 50 heures dans l'hôtellerie et la restauration.": "Dal lunedì alla domenica. La legge fissa 50 ore nel settore alberghiero e della ristorazione.",
  "Jours de repos par semaine": "Giorni di riposo a settimana",
  "Jours sans aucun horaire, comptés sur les semaines entières affichées.": "Giorni senza alcun orario, contati sulle settimane intere visualizzate.",
  "Aucun contrôle": "Nessun controllo",
  "1 jour": "1 giorno",
  "2 jours": "2 giorni",
  "Ces règles changent les heures comptées : soldes, relevé CCNT, exports des salaires, Comptabilité et Statistiques. Le pointage lui-même reste affiché et gardé tel quel.": "Queste regole cambiano le ore contate: saldi, riepilogo CCNL, esportazioni dei salari, Contabilità e Statistiche. La timbratura stessa resta visualizzata e conservata così com'è.",
  "Arrivée en avance": "Arrivo in anticipo",
  "Quand quelqu'un pointe avant l'heure prévue. Un retard compte toujours dès le pointage.": "Quando qualcuno timbra prima dell'ora prevista. Un ritardo conta sempre dalla timbratura.",
