  "Alerter dès une hausse de (%)": "Avvisa da un aumento del (%)",
  "Prix à l'unité (kilo, litre ou pièce) d'un article, comparé à son prix précédent chez le même fournisseur. Par défaut :": "Prezzo unitario (chilo, litro o pezzo) di un articolo, confrontato con il suo prezzo precedente presso lo stesso fornitore. Per impostazione predefinita:",
  "Un seuil entre 1 et 50 %.": "Una soglia tra 1 e 50 %.",
  "Seuil enregistré.": "Soglia salvata.",
  "Le seuil n'a pas pu être lu. Réessayez dans un instant.": "La soglia non si è potuta leggere. Riprovi tra un istante.",
