  "Dossier du contrôle": "Dossier del controllo",
  "Le PDF à remettre à l'inspecteur du contrôle des denrées.": "Il PDF da consegnare all'ispettore del controllo delle derrate.",
  "Par défaut, les": "Per impostazione predefinita, gli ultimi",
  "derniers jours. Sur cette période :": "giorni. In questo periodo:",
  "contrôles": "controlli",
  "contrôle": "controllo",
  "Le dossier reprend les relevés, les contrôles, les actions correctives, les problèmes signalés, les photos de traçabilité et les durées de vie des étiquettes. Sa dernière page liste ce que vous devez fournir à côté.": "Il dossier riprende le rilevazioni, i controlli, le azioni correttive, i problemi segnalati, le foto di tracciabilità e le durate di conservazione delle etichette. La sua ultima pagina elenca ciò che deve fornire a parte.",
  "Préparation du dossier…": "Preparazione del dossier…",
  "Choisissez une date de début et une date de fin.": "Scelga una data di inizio e una data di fine.",
  "La date de début doit venir avant la date de fin.": "La data di inizio deve venire prima della data di fine.",
  "La période commence après aujourd'hui.": "Il periodo inizia dopo oggi.",
  "Le dossier du contrôle est téléchargé.": "Il dossier del controllo è scaricato.",
  "Le dossier n'a pas pu être préparé.": "Il dossier non si è potuto preparare.",
