  "Revenir sans enregistrer": "Torna senza salvare",
  "Enregistrer quand même": "Salva comunque",
  "Autres points :": "Altri punti:",
  "Aucun point à signaler sur la période affichée.": "Nessun punto da segnalare nel periodo visualizzato.",
  "Jours de travail d'affilée": "Giorni di lavoro di fila",
  "Jour de repos entier": "Giorno di riposo intero",
  "Deux jours de repos par semaine": "Due giorni di riposo a settimana",
  "Pauses": "Pause",
  "Journée sur 14 heures au plus": "Giornata entro 14 ore al massimo",
  "Durée de la semaine": "Durata della settimana",
  "Ces repères se calculent sur les horaires prévus de la période affichée : repos, jours de repos, jours d'affilée, pauses et durée de la journée.": "Questi riferimenti si calcolano sugli orari previsti del periodo visualizzato: riposo, giorni di riposo, giorni di fila, pause e durata della giornata.",
  "Cet enregistrement ne respecte pas la règle suivante. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Questo salvataggio non rispetta la regola seguente. Può tornare indietro per correggere l'orario, o salvare comunque.",
  "Cet enregistrement ne respecte pas les règles suivantes. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Questo salvataggio non rispetta le regole seguenti. Può tornare indietro per correggere l'orario, o salvare comunque.",
  "La loi demande 11 heures, ou 8 heures une fois par semaine.": "La legge chiede 11 ore, o 8 ore una volta a settimana.",
  "C'est permis une fois par semaine, si la moyenne sur deux semaines atteint 11 heures.": "È permesso una volta a settimana, se la media su due settimane raggiunge 11 ore.",
  "Un seul repos de moins de 11 heures est permis par semaine.": "È permesso un solo riposo di meno di 11 ore a settimana.",
  "Septième jour d'affilée : permis si chaque journée reste sous 9 heures et si 83 heures de repos suivent.": "Settimo giorno di fila: permesso se ogni giornata resta sotto 9 ore e se seguono 83 ore di riposo.",
  "Septième jour d'affilée : prévoyez ensuite 83 heures de repos d'affilée.": "Settimo giorno di fila: preveda poi 83 ore di riposo di fila.",
  "Septième jour d'affilée avec une journée de plus de 9 heures. Six jours au plus, sept à titre d'exception.": "Settimo giorno di fila con una giornata di più di 9 ore. Sei giorni al massimo, sette a titolo eccezionale.",
  "Septième jour d'affilée sans 83 heures de repos à la suite. Six jours au plus, sept à titre d'exception.": "Settimo giorno di fila senza 83 ore di riposo di seguito. Sei giorni al massimo, sette a titolo eccezionale.",
  "Plus de sept jours de travail d'affilée. Six jours au plus, sept à titre d'exception.": "Più di sette giorni di lavoro di fila. Sei giorni al massimo, sette a titolo eccezionale.",
  "Aucun jour de repos entier dans la semaine. Un jour d'au moins 24 heures est obligatoire.": "Nessun giorno di riposo intero nella settimana. Un giorno di almeno 24 ore è obbligatorio.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 4 semaines.": "Un solo giorno di riposo nella settimana. Il secondo va restituito entro 4 settimane.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 12 semaines.": "Un solo giorno di riposo nella settimana. Il secondo va restituito entro 12 settimane.",
  "Pause trop courte pour la journée : 15 min au-delà de 5 h 30, 30 min au-delà de 7 h, 1 h au-delà de 9 h.": "Pausa troppo breve per la giornata: 15 min oltre 5 h 30, 30 min oltre 7 h, 1 h oltre 9 h.",
  "Un service de plus de 5 h 30 sans pause. Une pause de 15 min au moins est demandée.": "Un turno di più di 5 h 30 senza pausa. È richiesta una pausa di almeno 15 min.",
  "La journée doit tenir dans 14 heures, pauses comprises.": "La giornata deve stare entro 14 ore, pause comprese.",
  "Au-delà de la moyenne de la CCNT. Les heures en plus sont à compenser ou à payer.": "Oltre la media del CCNL. Le ore in più vanno compensate o pagate.",
  "Clore un pointage oublié après": "Chiudi una timbratura dimenticata dopo",
  "Si le départ n'est pas pointé, l'horaire est clos à l'heure de fin prévue, une fois ce délai passé depuis l'arrivée. Le contrôle passe toutes les heures. Le planning affiche l'horaire comme clos d'office. Un départ pointé ensuite, ou une correction, remplace cette heure.": "Se l'uscita non è timbrata, l'orario viene chiuso all'ora di fine prevista, una volta trascorso questo tempo dall'arrivo. Il controllo passa ogni ora. Il piano dei turni mostra l'orario come chiuso d'ufficio. Un'uscita timbrata in seguito, o una correzione, sostituisce quest'ora.",
