  "effet de la météo non mesurable : il faut au moins 8 jours de pluie ou de neige et 8 jours secs comparables. La météo s'affiche sans corriger la prévision.": "effetto del meteo non misurabile: servono almeno 8 giorni di pioggia o di neve e 8 giorni asciutti confrontabili. Il meteo si visualizza senza correggere la previsione.",
  "effet de la météo non mesurable : vos couverts ne changent pas assez entre jours de pluie et jours secs. La météo s'affiche sans corriger la prévision.": "effetto del meteo non misurabile: i Suoi coperti non cambiano abbastanza tra giorni di pioggia e giorni asciutti. Il meteo si visualizza senza correggere la previsione.",
  "effet de la météo non mesurable : aucune station de mesure MétéoSuisse à moins de 25 km. La météo s'affiche sans corriger la prévision.": "effetto del meteo non misurabile: nessuna stazione di misura MeteoSvizzera a meno di 25 km. Il meteo si visualizza senza correggere la previsione.",
