  "Les clients scannent le QR de l'établissement, choisissent leurs boissons et envoient la commande depuis leur téléphone. Elle arrive en caisse à valider : le bar l'accepte, ou la refuse avec un motif. Le client paie à table ou au comptoir.": "I clienti scansionano il QR della struttura, scelgono le loro bevande e inviano l'ordine dal loro telefono. Arriva in cassa da convalidare: il bar lo accetta, o lo rifiuta con un motivo. Il cliente paga al tavolo o al banco.",
