  'pointées': 'timbrate',
  'Les pourboires sont partagés à parts égales entre les personnes qui ont pointé sur la période.': 'Le mance sono ripartite in parti uguali tra le persone che hanno timbrato nel periodo.',
  'Les pourboires sont partagés selon les heures pointées de chacun.': 'Le mance sono ripartite secondo le ore timbrate di ciascuno.',
  'Chaque groupe reçoit sa part, puis elle est partagée selon les heures pointées de chacun.': 'Ogni gruppo riceve la sua quota, poi ripartita secondo le ore timbrate di ciascuno.',
  'Aucune règle de partage n\'est réglée. Vous la réglez dans Réglages, Caisse, Pourboires.': 'Nessuna regola di ripartizione è impostata. La imposta in Impostazioni, Cassa, Mance.',
  'La règle de partage ne correspond plus aux groupes du Planning. Vous la corrigez dans Réglages, Caisse, Pourboires.': 'La regola di ripartizione non corrisponde più ai gruppi del Planning. La corregge in Impostazioni, Cassa, Mance.',
  'Aucune heure pointée sur cette période. Le partage ne peut pas se calculer.': 'Nessuna ora timbrata in questo periodo. La ripartizione non si può calcolare.',
  'Personne de ce groupe n\'a pointé sur la période. Sa part n\'est pas répartie.': 'Nessuno di questo gruppo ha timbrato nel periodo. La sua quota non è ripartita.',
  'Ces personnes ont pointé sans faire partie d\'un groupe retenu par la règle. Elles ne reçoivent rien.': 'Queste persone hanno timbrato senza far parte di un gruppo previsto dalla regola. Non ricevono nulla.',
  'Les heures pointées n\'ont pas pu être lues. Réessayez.': 'Non è stato possibile leggere le ore timbrate. Riprovi.',
  'Les groupes ou les règles de pointage n\'ont pas pu être lus. Réessayez.': 'Non è stato possibile leggere i gruppi o le regole di timbratura. Riprovi.',
