  'Lecture des groupes du Planning…': 'Lettura dei gruppi del Planning…',
  'Les groupes du Planning n\'ont pas pu être lus. La règle de partage ne peut pas se régler pour le moment.': 'Non è stato possibile leggere i gruppi del Planning. La regola di ripartizione non si può impostare per ora.',
  'La règle de partage s\'appuie sur les groupes du Planning, Salle et Cuisine par exemple. Créez-les d\'abord dans Réglages, Planning, Groupes.': 'La regola di ripartizione si basa sui gruppi del Planning, Sala e Cucina per esempio. Li crei prima in Impostazioni, Planning, Gruppi.',
  'Les pourboires saisis à l\'encaissement sont partagés dans le rapport de la caisse, onglet Pourboires. Ils restent hors chiffre d\'affaires. Rien n\'est versé ni écrit en comptabilité.': 'Le mance registrate all\'incasso sono ripartite nel rapporto della cassa, scheda Mance. Restano fuori dal fatturato. Nulla viene versato né registrato in contabilità.',
